* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, "Segoe UI", sans-serif; font-size: 16px; background: #122c37; color: #f4f2e8; }
body { min-width: 360px; min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #25505a 0, #122c37 64%); }
.booking-card { width: min(100%, 490px); padding: 32px; border: 1px solid #45656a; border-radius: 24px; background: #1b3942; box-shadow: 0 24px 70px #07181d88; }
.header { text-align: center; margin-bottom: 24px; }
.eyebrow, .summary-label { margin: 0; color: #b9d77a; font-size: 0.8rem; font-weight: 750; letter-spacing: .12em; }
h1 { margin: 9px 0 5px; font-size: clamp(1.8rem, 8vw, 2.35rem); line-height: 1.1; letter-spacing: -.04em; }
.intro { margin: 0; color: #c5d3ce; }
.legend { display: flex; justify-content: center; flex-wrap: wrap; gap: 18px; margin-bottom: 14px; color: #d4dfd9; font-size: .9rem; }
.legend span { display: inline-flex; align-items: center; gap: 7px; }
.key { width: 14px; height: 14px; border-radius: 4px; background: #d6e8bd; }
.key.selected { background: #b9d77a; }
.key.booked { background: #637a7b; }
.bus { max-width: 330px; margin: 0 auto; padding: 14px 16px 17px; border: 1px solid #527075; border-radius: 50px 50px 20px 20px; background: #15323b; }
.driver { height: 34px; display: flex; align-items: center; justify-content: space-between; margin: 0 4px 13px; padding: 0 7px; color: #91aaa7; font-size: .72rem; letter-spacing: .1em; }
.wheel { display: grid; width: 28px; height: 28px; place-items: center; border: 2px solid #527075; border-radius: 50%; font-size: 1rem; }
.seat-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)) 24px repeat(2, minmax(0, 1fr)); gap: 8px 6px; }
.seat { min-height: 39px; border: 1px solid #b2caa1; border-radius: 9px 9px 5px 5px; background: #d6e8bd; color: #1c3535; font: inherit; font-size: .9rem; font-weight: 750; cursor: pointer; transition: transform .12s, background .12s, box-shadow .12s; }
.seat:hover:not(:disabled) { transform: translateY(-2px); background: #eff7de; }
.seat:active:not(:disabled) { transform: scale(.96); }
.seat:focus-visible, .clear-button:focus-visible { outline: 3px solid #f3cf76; outline-offset: 3px; }
.seat.selected { border-color: #b9d77a; background: #b9d77a; box-shadow: inset 0 0 0 2px #769646; }
.seat:disabled { border-color: #637a7b; background: #637a7b; color: #d0d8d1; cursor: not-allowed; }
.aisle { display: grid; place-items: center; color: #66817f; font-size: .72rem; }
.summary { margin-top: 22px; padding: 18px; border: 1px solid #45656a; border-radius: 16px; background: #21434a; }
.summary-top { display: flex; justify-content: space-between; gap: 16px; align-items: flex-start; }
.summary-label { color: #aac4b7; font-size: .73rem; }
.chosen, .total { margin: 6px 0 0; font-size: 1.05rem; font-weight: 700; }
.chosen { overflow-wrap: anywhere; }
.total-block { text-align: right; flex: 0 0 auto; }
.total { color: #f3cf76; font-size: 1.75rem; line-height: 1; }
.total::before { content: "¤"; margin-right: 4px; font-size: 1rem; vertical-align: 3px; }
.price-note { margin: 12px 0 0; color: #c5d3ce; font-size: .9rem; }
.status { min-height: 1.35em; margin: 8px 0 0; color: #f3cf76; font-size: .88rem; }
.clear-button { width: 100%; min-height: 46px; margin-top: 10px; border: 1px solid #91aaa7; border-radius: 10px; background: transparent; color: #f4f2e8; font: inherit; font-weight: 700; cursor: pointer; transition: background .15s, transform .12s; }
.clear-button:hover { background: #31545a; }
.clear-button:active { transform: scale(.99); }
footer { margin-top: 18px; color: #aec2ba; text-align: center; font-size: .88rem; }
footer span { color: #f3cf76; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (max-width: 420px) { body { padding: 18px 12px; } .booking-card { padding: 24px 18px; } .bus { padding-inline: 12px; } .seat-grid { gap: 7px 5px; grid-template-columns: repeat(2, minmax(0, 1fr)) 18px repeat(2, minmax(0, 1fr)); } }

const grid = document.querySelector('#seat-grid');
const chosenOutput = document.querySelector('#chosen-seats');
const totalOutput = document.querySelector('#total-price');
const noteOutput = document.querySelector('#price-note');
const statusOutput = document.querySelector('#status');
const selected = new Set();
const booked = new Set(['1B', '3C', '5A', '7D', '9B']);

for (let row = 1; row <= 10; row += 1) {
  for (const column of ['A', 'B', 'C', 'D']) {
    if (column === 'C') {
      const aisle = document.createElement('span');
      aisle.className = 'aisle';
      aisle.setAttribute('aria-hidden', 'true');
      aisle.textContent = '·';
      grid.append(aisle);
    }
    const code = `${row}${column}`;
    const seat = document.createElement('button');
    seat.type = 'button';
    seat.className = 'seat';
    seat.textContent = code;
    seat.setAttribute('aria-label', `Seat ${code}${booked.has(code) ? ', booked' : ', available'}`);
    seat.setAttribute('aria-describedby', 'selection-help');
    seat.disabled = booked.has(code);
    if (seat.disabled) seat.setAttribute('aria-pressed', 'false');
    seat.addEventListener('click', () => toggleSeat(code, seat));
    grid.append(seat);
  }
}

function toggleSeat(code, seat) {
  statusOutput.textContent = '';
  if (selected.has(code)) {
    selected.delete(code);
  } else if (selected.size >= 4) {
    statusOutput.textContent = 'You can select up to four seats.';
    return;
  } else {
    selected.add(code);
  }
  seat.classList.toggle('selected', selected.has(code));
  seat.setAttribute('aria-pressed', String(selected.has(code)));
  updateSummary();
}

function updateSummary() {
  const codes = [...selected].sort((a, b) => Number(a.slice(0, -1)) - Number(b.slice(0, -1)) || a.localeCompare(b));
  const discounted = selected.size === 4;
  const total = selected.size * 12 * (discounted ? 0.9 : 1);
  chosenOutput.textContent = codes.length ? codes.join(', ') : 'None selected';
  totalOutput.textContent = Number.isInteger(total) ? String(total) : total.toFixed(2);
  noteOutput.textContent = discounted ? '12 per seat · 10% discount applied' : '12 per seat';
}

document.querySelector('#clear-button').addEventListener('click', () => {
  for (const code of selected) {
    const seat = [...grid.querySelectorAll('.seat')].find(button => button.textContent === code);
    seat.classList.remove('selected');
    seat.setAttribute('aria-pressed', 'false');
  }
  selected.clear();
  statusOutput.textContent = '';
  updateSummary();
});
